// INGESTION + NORMALIZATION: schedule / webhook / telegram -> Event schema chung.
const raw = $input.first().json;
const body = raw.body || {};
const now = new Date();
const p = (n) => String(n).padStart(2, '0');
const stamp = `${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}_${p(now.getHours())}${p(now.getMinutes())}`;
const uid = Math.random().toString(36).slice(2, 8);
let event;
if (raw.chat) {
  event = { type: 'telegram_chat', entity: String((raw.chat && raw.chat.id) || 'unknown'), payload: { text: raw.text || '', chat_id: (raw.chat && raw.chat.id) || null, from: (raw.from && raw.from.username) || '', source: 'telegram' } };
} else if (raw.body) {
  event = { type: body.type || 'business_event', entity: body.entity || 'unknown', payload: body.payload || {} };
} else {
  event = { type: 'inventory_check', entity: 'product_A', payload: { stock: 15, avg_daily_sales: 8 } };
}
// TODO: thay payload demo bang node Fetch (Sheets/ERP/CRM) truoc Normalize.
const prefix = event.payload && event.payload.source === 'telegram' ? 'tg' : 'run';
return [{ json: {
  correlation_id: body.correlation_id || `${prefix}_${stamp}_${uid}`,
  event,
  context: { history_window_days: 30, requested_by: 'dailyops-unified' }
}}];

