// REPORT branch: chuan bi dong bao cao cho Google Sheets.
const d = $input.first().json;
return [{ json: { date: new Date().toISOString(), summary: d.decision.summary, confidence: d.decision.confidence, correlation_id: d.correlation_id } }];

