// Resume sau approval: lay lai action da duoc human duyet (tu approvals row) + idempotency_key goc de dedup khi execute.
const r = $input.first().json;
return [{ json: { correlation_id: r.correlation_id, recommended_action: r.requested_action, idempotency_key: r.idempotency_key || '' } }];

// Failure outcome (verified=false) + audit row. Khong phu thuoc notify.
const f = $input.first().json;
const action = f.action_type || (f.requested_action ? 'EXECUTE' : 'UNKNOWN');
return [{ json: { correlation_id: f.correlation_id || 'unknown', action_type: action, actor: 'n8n', event: 'system.workflow_failed', verified: false, error: f.error || JSON.stringify(f).slice(0, 500), timestamp: new Date().toISOString() } }];

// DAILYOPS-08: phan biet UNKNOWN_OUTCOME (timeout — co the da thanh cong) va FAILED (chac chan that bai).
// Chinh sach: KHONG BAO GIO blind-retry side-effect. UNKNOWN_OUTCOME phai qua reconciliation
// (re-query external state bang external_operation_id) truoc khi quyet retry; FAILED -> escalate human.
const f = $input.first().json;
const err = String(f.error || '');
const unknown = /timeout|timed?[ _-]?out|ECONNABORTED|ETIMEDOUT|ECONNRESET|socket hang up|aborted/i.test(err);
const outcome_kind = unknown ? 'UNKNOWN_OUTCOME' : 'FAILED';
return [{ json: { ...f, outcome_kind, retry_policy: unknown ? 'reconcile_before_retry' : 'no_auto_retry', reconciliation_needed: unknown, external_operation_id: f.external_operation_id || f.operation_id || null, escalated: true } }];

// Escalation stub: chuan bi thong bao cho human.
const f = $input.first().json;
return [{ json: { ...f, escalation: { channel: 'telegram', text: `[ESCALATION] ${f.correlation_id}: ${f.error}` } } }];

