const sup = $('Attach Channel Context').first().json;
function get(n){ try { return $(n).first().json; } catch(e){ return null; } }
const parts = ['Specialist — Business Analyst','Specialist — Knowledge Agent','Specialist — Operations Agent','Specialist — Report Agent'].map(get).filter(Boolean);
const evidence = [];
const errs = [];
parts.forEach((p) => { if (p.error) { errs.push((p.agent || 'unknown') + ': ' + String(p.error).slice(0, 200)); return; } (p.evidence || []).forEach((e) => evidence.push({ source: (p.agent || '?') + ':' + (e.source || ''), content: String(e.content || '').slice(0, 300), score: e.score || 0 })); });
(sup.evidence || []).forEach((e) => evidence.push(e));
const used = parts.map((p) => p.agent).filter(Boolean);
