return [{ json: { ...sup, specialists_used, evidence, specialist_errors: errs, aggregated_at: new Date().toISOString() } }];

const agent = $('Route by action_type').first().json;
const out = $input.first().json;
// Check if sheet append succeeded
const sheetSuccess = out.verified === true || out.verified === undefined;
// If we can't determine success, classify as UNKNOWN_OUTCOME for reconciliation
const outcome_kind = sheetSuccess ? 'SUCCESS' : 'UNKNOWN_OUTCOME';
return [{ json: { correlation_id: agent.correlation_id || 'unknown', action_type: 'REPORT', verified: sheetSuccess, outcome_kind } }];

const agent = $('Route by action_type').first().json;
const out = $input.first().json;
// Check notification delivery status
// If delivery status uncertain (timeout, no acknowledgment), classify as UNKNOWN_OUTCOME
const deliverySuccess = out.verified === true || out.verified === undefined;
const outcome_kind = deliverySuccess ? 'SUCCESS' : 'UNKNOWN_OUTCOME';
return [{ json: { correlation_id: agent.correlation_id || 'unknown', action_type: 'NOTIFY', verified: deliverySuccess, outcome_kind } }];

const agent = $('Route by action_type').first().json;
const out = $input.first().json;
// Distinguish: definitive failure vs uncertain outcome
// If out.error exists or execution explicitly failed -> FAILED
// If timeout / network error with uncertain external state -> UNKNOWN_OUTCOME
// If success -> SUCCESS
let outcome_kind = 'SUCCESS';
let verified = true;
if (out.error) {
  verified = false;
  outcome_kind = 'FAILED';
} else if (out.timeout || out.timed_out) {
  verified = false;
  outcome_kind = 'UNKNOWN_OUTCOME';
}
return [{ json: { correlation_id: agent.correlation_id || 'unknown', action_type: 'EXECUTE', verified, outcome_kind } }];
